// 统计
export const MEDIA_COUNT = adlerMedia.length;
export const MEDIA_PUBLIC_READY = adlerMedia.filter(m => m.reviewStatus === 'public_ready').length;

// seed 影视 ID 列表
export const SEED_MEDIA_IDS = adlerMedia
  .filter(m => m.id.startsWith('media_seed_'))
  .map(m => m.id);

// 按类型索引
export const mediaByType: Record<string, MediaStory[]> = {};
adlerMedia.forEach(m => {
  if (m.reviewStatus !== 'public_ready') return;
  if (!mediaByType[m.type]) mediaByType[m.type] = [];
  mediaByType[m.type].push(m);
});

// 按 Lens 索引
export const mediaByLens: Record<string, MediaStory[]> = {};
adlerMedia.forEach(m => {
  if (m.reviewStatus !== 'public_ready') return;
  m.adlerianLensTags.forEach(lens => {
    if (!mediaByLens[lens]) mediaByLens[lens] = [];
    mediaByLens[lens].push(m);
  });
});

// 按 Pair 索引
export const mediaByPair: Record<string, MediaStory[]> = {};
adlerMedia.forEach(m => {
  if (m.reviewStatus !== 'public_ready') return;
  m.pairTags.forEach(pair => {
    if (!mediaByPair[pair]) mediaByPair[pair] = [];
    mediaByPair[pair].push(m);
  });
});

// 按场景索引
export const mediaByScene: Record<string, MediaStory[]> = {};
adlerMedia.forEach(m => {
  if (m.reviewStatus !== 'public_ready') return;
  m.contextTags.forEach(scene => {
    if (!mediaByScene[scene]) mediaByScene[scene] = [];
    mediaByScene[scene].push(m);
  });
});

// 匹配影视（Why You 检索）
export function findMatchingMedia(
  profileScores: Record<string, number>,
  pairPatterns: string[],
  currentLifeTask: string,
  currentScene: string,
  mediaType?: string,
  limit = 2,
): MediaStory[] {
  const scored = adlerMedia
    .filter(m => {
      if (m.reviewStatus !== 'public_ready') return false;
      if (mediaType && m.type !== mediaType) return false;
      return true;
    })
    .map(m => {
      let score = 0;

      // 场景匹配 (权重最高)
      if (m.contextTags.includes(currentScene)) score += 0.30;

      // Pair 匹配
      const pairMatch = m.pairTags.filter(pt => pairPatterns.includes(pt)).length / Math.max(pairPatterns.length, 1);
      score += pairMatch * 0.25;

      // Life task 匹配
      if (m.lifeTaskTags.includes(currentLifeTask)) score += 0.15;

      // Lens 匹配
      const lensMatch = m.adlerianLensTags.length / 7;
      score += lensMatch * 0.15;

      // Seed 作品优先
      if (m.id.startsWith('media_seed_')) score += 0.10;

      // 有内容警告的稍微降权（除非场景特别相关）
      if (m.contentWarning && !m.contextTags.includes(currentScene)) score -= 0.05;

      return { media: m, score };
    });

  scored.sort((a, b) => b.score - a.score);

  return scored.slice(0, limit).map(s => s.media);
}

// 验证影视库完整性
export function validateMediaCorpus(): {
  total: number;
  publicReady: number;
  seedCount: number;
  types: Record<string, number>;
  ready: boolean;
} {
  const publicReady = adlerMedia.filter(m => m.reviewStatus === 'public_ready');
  const seedCount = adlerMedia.filter(m => m.id.startsWith('media_seed_')).length;

  const types: Record<string, number> = {};
  publicReady.forEach(m => {
    types[m.type] = (types[m.type] || 0) + 1;
  });

  const ready = publicReady.length >= 360 && seedCount >= 10;

  return {
    total: adlerMedia.length,
    publicReady: publicReady.length,
    seedCount,
    types,
    ready,
  };
}
